actions.script:
try {
    sessionCount = ec.user.endVisit(visitId)
} catch (e) {
    ec.message.addError(String(e.message || e))
}

field-map.from:
{userAccount: {userId: userAccount.get('userId'), username: userAccount.get('username'),
                        userFullName: userAccount.get('userFullName'), emailAddress: userAccount.get('emailAddress'),
                        requirePasswordChange: userAccount.get('requirePasswordChange')}, resetPassword: resetPassword}

actions.script:
const purpose = ec.factory.getConfValue('instance@purpose')
let offered = false
if (purpose === 'dev' || purpose === 'test' || ec.factory.getConfValue('demo@test-login') === 'true') {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', 'EX_JOHN_DOE').disableAuthz().one()
    const stored = account ? String(account.currentPassword ?? '') : ''
    if (stored) {
        const cache = ec.cache.getCache('webroot.login.test')
        const key = ec.resource.digestText(stored)
        const cached = cache.get(key)
        if (cached != null) {
            offered = cached === true
        } else {
            offered = ec.user.passwordsMatch('moqui', stored, account.passwordHashType, account.passwordSalt,
                account.passwordBase64 == 'Y') === true
            cache.put(key, offered)
        }
    }
}
context.offered = offered

allowed = false
const me = ec.user.userId
if (!me || ec.artifactExecution.authzDisabled()) allowed = true
else if (userId === me) {
    allowed = !recentAuth || !!ec.service.sync().name('org.moqui.sso.RecentAuthServices.require#RecentAuth').call()?.recent
} else if (permissionId !== 'NONE' && !ec.user.hasPermission(permissionId)) {
    ec.message.addError(ec.l10n.localize('That account is not yours'))
} else {
    const held = bounded ? ec.resource.script('component://framework/service/org/moqui/admin/Identity.js').heldBeyond(userId) : null
    if (held) ec.message.addError(held + ': ' + ec.l10n.localize('that account is not yours to change'))
    // an administrator's action on another account that makes or ends its codes or factors, or changes its email
    // or provider link, asks the same recent sign-in as the owner's own (a stolen session takes over no account)
    else allowed = !recentAuth || !!ec.service.sync().name('org.moqui.sso.RecentAuthServices.require#RecentAuth').call()?.recent
}
